const HUIDTINT = '#E3B998';

// ---------- de tijdlijn (terugkerend beeld) ----------
const TL = { x0: 150, x1: 1770, y: 140, knik: 380 };
function tlx(j) { if (j < 1500) return TL.x0 + (j + 400) / 1900 * (TL.knik - TL.x0 - 20); return TL.knik + (j - 1500) / 530 * (TL.x1 - TL.knik); }
const MARK = [[-340, 'Aristoteles'], [170, 'Galenus'], [1242, 'Ibn al-Nafis'], [1543, 'Vesalius'], [1628, 'Harvey'], [1665, 'Hooke'], [1676, 'Van Leeuwenhoek'], [1758, 'Linnaeus'], [1847, 'Semmelweis'], [1854, 'Snow'], [1859, 'Darwin'], [1862, 'Pasteur'], [1866, 'Mendel'], [1928, 'Fleming'], [1953, 'DNA'], [1962, 'Carson'], [2012, 'CRISPR']];
function jaarTekst(j) { return j < 0 ? (-j) + ' v.Chr.' : j < 1000 ? j + ' n.Chr.' : String(j); }
// o: { a, span:[j0,j1], jaar, naam, alles }  — span = deel van de tijdlijn dat dit hoofdstuk beslaat (goud), jaar = huidige markering
function tijdlijn(ctx, o = {}) { const { a = 1, span = null, jaar = null, alles = 0, toon = [] } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a;
  const y = TL.y; ctx.strokeStyle = C.line; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(TL.x0, y); ctx.lineTo(TL.knik - 26, y); ctx.moveTo(TL.knik - 6, y); ctx.lineTo(TL.x1 + 30, y); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(TL.knik - 30, y + 10); ctx.lineTo(TL.knik - 20, y - 10); ctx.moveTo(TL.knik - 12, y + 10); ctx.lineTo(TL.knik - 2, y - 10); ctx.stroke(); pijl(ctx, TL.x1 + 20, y, TL.x1 + 44, y, C.line, 1, 2, 12);
  metaText(ctx, 'oudheid', (TL.x0 + TL.knik - 30) / 2, y + 44, C.text2, 'center', 26);
  for (let j = 1500; j <= 2000; j += 100) { const x = tlx(j); ctx.strokeStyle = C.line; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(x, y - 6); ctx.lineTo(x, y + 6); ctx.stroke(); metaText(ctx, String(j), x, y + 44, C.text2, 'center', 26); }
  if (span) { const x0 = tlx(span[0]), x1 = tlx(span[1]); roundRect(ctx, x0 - 10, y - 9, x1 - x0 + 20, 18, 9); ctx.fillStyle = rgba(C.goud, 0.28); ctx.fill(); ctx.strokeStyle = rgba(C.goud, 0.8); ctx.lineWidth = 1.2; ctx.stroke(); }
  for (const [j, n] of MARK) { const x = tlx(j), inSpan = span && j >= span[0] && j <= span[1], zie = alles || inSpan || toon.includes(n); circ(ctx, x, y, zie ? 7 : 5, zie ? C.text : rgba(C.line, 0.7), null); }
  if (jaar != null) { const x = tlx(jaar); ctx.fillStyle = C.goud; ctx.beginPath(); ctx.arc(x, y, 12, 0, 6.283); ctx.fill(); ctx.strokeStyle = C.bgSchema; ctx.lineWidth = 3; ctx.stroke(); metaText(ctx, jaarTekst(jaar), clamp(x, 180, 1740), y - 26, C.goud, 'center', 28); }
  ctx.restore(); }
// geanimeerde jaarmarkering: van j0 naar j1 tussen t0 en t0+d
function jaarNaar(q, w, n, j0, j1, d = 1.4) { const u = ease((q.localT - q.at(w, n)) / d); return Math.round(lerp(j0, j1, u)); }

