let _off = null; function viaOff(ctx, a, draw) { const ga = ctx.globalAlpha * a; if (ga > 0.985) return draw(ctx); if (ga <= 0.01) return {}; if (!_off) { _off = document.createElement('canvas'); _off.width = W; _off.height = H; } const o = _off.getContext('2d'); o.setTransform(1, 0, 0, 1, 0, 0); o.clearRect(0, 0, W, H); o.globalAlpha = 1; o.setTransform(ctx.getTransform()); const r = draw(o); ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.globalAlpha = ga; ctx.drawImage(_off, 0, 0); ctx.restore(); return r; }
function fig(ctx, id, x, y, h, o = {}) { const a = o.a == null ? 1 : o.a; return viaOff(ctx, a, (c) => persoon(c, id, x, y, h, Object.assign({}, o, { a: 1 }))); }

