  if (id === 'aristoteles' || id === 'galenus') { ctx.fillStyle = id === 'aristoteles' ? '#CFC6AE' : '#E6DFCC'; ctx.beginPath(); ctx.moveTo(hx - hr * 1.5, hy + hr * 1.5); ctx.lineTo(hx + hr * 1.4, hy + hr * 5.5); ctx.lineTo(hx + hr * 1.9, hy + hr * 5.0); ctx.lineTo(hx - hr * 0.9, hy + hr * 1.3); ctx.closePath(); ctx.fill(); }
